	private static void assertProofInterrupted(Signal signal, Timing timing, GraphRead operation) throws Exception {
		var visited = new AtomicInteger();
		var reached = new CountDownLatch(1);
		var resume = new CountDownLatch(1);
		var tripDeadline = new AtomicReference<Runnable>();
		var token = new AtomicReference<>();
		var lookup = observeContinuations(continuation -> {
			visited.incrementAndGet();
			if (continuation == timing.continuation) {
				if (signal == Signal.TERMINAL) {
					reached.countDown();
					await(resume);
				} else {
					tripDeadline.get().run();
				}
			}
		});
		if (signal == Signal.TERMINAL) {
			var stopped = assertThrows(KernelQueryCancelledException.class,
					() -> NativeCancellationTestAccess.cancelAfter(reached, resume, token::set, () -> {
						operation.run(lookup, NativeLmdbQuerySource.captureCursorCancellation());
						return null;
					}));
			assertSame(token.get(), stopped.origin());
			assertTrue(stopped.observedBy(token.get()));
		} else {
			var stopped = assertThrows(RuntimeException.class,
					() -> NativeCancellationTestAccess.withTrippableProbeDeadline(tripDeadline::set, () -> {
						operation.run(lookup, NativeLmdbQuerySource.captureCursorCancellation());
						return null;
					}));
			assertSame(NativeCancellationTestAccess.probeDeadlineSignal(), stopped);
		}
		if (timing == Timing.EARLY) {
			assertTrue(visited.get() < FRAGMENTS - 1, "Cancellation must stop the continuation walk");
		} else {
			assertEquals(FRAGMENTS - 1, visited.get(), "Stop was published on the final continuation");
		}
	}

	private static ImmutablePagedQuadCsfIndex observeContinuations(IntConsumer consumer) {
		var lookup = mock(ImmutablePagedQuadCsfIndex.class, delegatesTo(index));
		doAnswer(invocation -> {
			Runnable poll = invocation.getArgument(5);
			var continuation = new AtomicInteger();
			return index.findLocalReference(invocation.getArgument(0), invocation.getArgument(1),
					invocation.getArgument(2), invocation.getArgument(3), invocation.getArgument(4), () -> {
						if (poll != null) {
							poll.run();
						}
						consumer.accept(continuation.incrementAndGet());
					});
		}).when(lookup)
				.findLocalReference(anyLong(), eq(0), eq(ROOT),
						isA(ImmutablePagedQuadCsfIndex.LookupCursor.class), eq(ABSENT), any());
		return lookup;
	}

