	@ParameterizedTest
	@MethodSource("strictPublicationMisses")
	void pendingAndOverlayMissesKeepExactCheckpoint(boolean pendingRow, long overlayVersion) throws IOException {
		var owner = recordingOwner();
		try (var arena = new LmdbAdjacencyArena(1L << 16);
				var catalog = LmdbAdjacencyArenaCatalog.of(arena, index);
				var contexts = LmdbAdjacencyContextCatalog.base(arena, new long[] { COMMON, LAST, ABSENT })) {
			var baseState = exactState(arena, catalog, contexts, index, 1L);
			PendingTable[] pending = null;
			LmdbAdjacencyOverlaySet overlays = null;
			if (pendingRow) {
				var table = new PendingTable(new long[] { SHORT_ROOT }, new long[] { PREDICATE }, new byte[] { 0 });
				table.stampRevision(2L);
				pending = new PendingTable[] { table };
			} else {
				var generation = mock(LmdbAdjacencyDeltaGeneration.class);
				when(generation.revision()).thenReturn(2L);
				when(generation.find(SHORT_ROOT, 0, PREDICATE)).thenReturn(overlayVersion);
				overlays = mock(LmdbAdjacencyOverlaySet.class);
				when(overlays.generationCount()).thenReturn(1);
				when(overlays.generation(0)).thenReturn(generation);
			}
			var state = new LmdbAdjacencyPublishedState(2L, baseState.base(), overlays, pending, pendingRow ? 1L : 2L,
					Long.MAX_VALUE, baseState.servingState(), 1L, baseState.planeStatistics());
			try (var view = LmdbAdjacencyReadView.exact(2L, state, null);
					var result = Route.ONE_SIDED.open(view, SHORT_ROOT, ABSENT, owner)) {
				if (pendingRow) {
					assertNull(result, "A pending row must fall back to LMDB");
				} else {
					assertSame(EmptyRecordIterator.INSTANCE, result);
				}
				verify(owner).checkpoint();
				verify(owner).checkpointNow();
			}
		}
	}

